//! Inner Sea Faiths shared spell list.
//!
//! Generated by `src/bin/ingest_inner_sea_setting_spells.rs` from the
//! real `pathfinder/paizo/campaign_setting/inner_sea_faiths/isf_spells.lst` corpus (SD-32 Gate 0 book-onboarding precondition,
//! `gate-0-book-onboarding-precondition`, AT-32-G0-003). Record coverage:
//! every real, active (non-`.MOD`, non-`.COPY=`) base spell declaration.
//!
//! `level` is the minimum level across the record's `CLASSES:`/`DOMAINS:`
//! token(s) (the `rules_tables::acg::spell_list` precedent), `None` for the
//! rare record that states neither (never fabricated -- these land
//! `text-complete`, not `ingested-magnitude`, via
//! `v06_work_inventory::classify`'s existing `Some(false)` branch).
//!
//! `school`/`description` are `Option` (mirroring
//! `rules_tables::adventurers_guide::spell_list`'s own shape) because a
//! minority of records carry neither token of their own on this book's
//! base row.

/// The full 9-school PF1 spell-school enum, mirroring every other book's
/// own copy exactly.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Pf1SchoolId {
    Abjuration,
    Conjuration,
    Divination,
    Enchantment,
    Evocation,
    Illusion,
    Necromancy,
    Transmutation,
    Universal,
}

impl Pf1SchoolId {
    pub fn from_corpus_str(raw: &str) -> Option<Self> {
        match raw {
            "Abjuration" => Some(Pf1SchoolId::Abjuration),
            "Conjuration" => Some(Pf1SchoolId::Conjuration),
            "Divination" => Some(Pf1SchoolId::Divination),
            "Enchantment" => Some(Pf1SchoolId::Enchantment),
            "Evocation" => Some(Pf1SchoolId::Evocation),
            "Illusion" => Some(Pf1SchoolId::Illusion),
            "Necromancy" => Some(Pf1SchoolId::Necromancy),
            "Transmutation" => Some(Pf1SchoolId::Transmutation),
            "Universal" => Some(Pf1SchoolId::Universal),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SpellListEntry {
    pub key: &'static str,
    pub school: Option<Pf1SchoolId>,
    pub level: Option<u8>,
    pub description: Option<&'static str>,
}

pub const SPELL_LIST: &[SpellListEntry] = &[
    SpellListEntry { key: "Curse of Disgust (Besmaran)", school: Some(Pf1SchoolId::Enchantment), level: None, description: Some("Target is sickened when viewing a trigger.") },
    SpellListEntry { key: "Geas (Lesser/Besmaran)", school: Some(Pf1SchoolId::Enchantment), level: None, description: Some("A lesser geas places a magical command on a creature to carry out some service or to refrain from some action or course of activity, as desired by you.") },
];
